package conversation_test

import (
	. "github.com/mudler/go-chatgpt-conversation"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"github.com/otiai10/openaigo"
)

var _ = Describe("test options", func() {
	Context("constructor", func() {
		It("can set history", func() {
			testHistory := []openaigo.ChatMessage{
				{Role: "system", Content: "foo"},
				{Role: "user", Content: "bar"},
				{Role: "assistant", Content: "response"}}

			cat, err := New("none",
				WithHistory(
					testHistory,
				),
			)
			Expect(err).ToNot(HaveOccurred())
			Expect(cat.History).To(Equal(testHistory))
		})
		It("can set initial prompt", func() {
			expectedHistory := []openaigo.ChatMessage{
				{Role: "system", Content: "foo"},
			}
			cat, err := New("none",
				WithInitialPrompt("foo"),
			)
			Expect(err).ToNot(HaveOccurred())
			Expect(cat.History).To(Equal(expectedHistory))
		})
	})
})

package conversation_test

import (
	"os"
	"path/filepath"

	. "github.com/mudler/go-chatgpt-conversation"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"github.com/otiai10/openaigo"
)

var _ = Describe("ask to gpt", func() {
	Context("conversation", func() {
		It("can track history", func() {
			if os.Getenv("OPENAI_API_TOKEN") == "" {
				Skip("OPENAI_API_TOKEN required to run this test")
			}
			cat, err := New(os.Getenv("OPENAI_API_TOKEN"),
				WithInitialPrompt("You are a cat. You can reply with 'Meow' for yes, and 'Meow Meow' for no."))
			Expect(err).ToNot(HaveOccurred())

			res, err := cat.User("Are you a cat?")
			Expect(err).ToNot(HaveOccurred())

			Expect(res).To(Equal("Meow."))

			res, err = cat.Chat("Are you a human?")
			Expect(err).ToNot(HaveOccurred())

			Expect(res).To(Equal("Meow Meow."))
		})

		It("can save history", func() {
			testHistory := []openaigo.ChatMessage{
				{Role: "system", Content: "foo"},
				{Role: "user", Content: "bar"},
				{Role: "assistant", Content: "response"}}

			cat, err := New("none",
				WithHistory(
					testHistory,
				),
			)
			Expect(err).ToNot(HaveOccurred())
			dir, err := os.MkdirTemp("", "test")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			f := filepath.Join(dir, "test.json")

			err = cat.Save(f)
			Expect(err).ToNot(HaveOccurred())

			conv, err := Load(f, "test")
			Expect(err).ToNot(HaveOccurred())

			Expect(conv.History).To(Equal(testHistory))
		})
	})
})

package conversation

import (
	"context"
	"encoding/json"
	"fmt"
	"os"

	"github.com/otiai10/openaigo"
)

const (
	roleSystem    = "system"
	roleUser      = "user"
	roleAssistant = "assistant"

	defaultModel = "gpt-3.5-turbo"
)

// Conversation is the abstract conversation view.
type Conversation struct {
	History []openaigo.ChatMessage
	apiKey  string
	model   string
	ctx     context.Context
}

// New creates a new conversation.
// Requires an OpenAI API key, and an optional list of options.
// It returns a new conversation and an error if there is a failure.
func New(apiKey string, opts ...Option) (*Conversation, error) {
	if apiKey == "" {
		return nil, fmt.Errorf("an API key is required")
	}
	c := &Conversation{apiKey: apiKey, model: defaultModel}
	for _, o := range opts {
		if err := o(c); err != nil {
			return nil, err
		}
	}
	return c, nil
}

// Load loads a conversation from the disk with the given options.
func Load(file, apiKey string, opts ...Option) (*Conversation, error) {
	b, err := os.ReadFile(file)
	if err != nil {
		return nil, err
	}

	msgs := []openaigo.ChatMessage{}

	if err := json.Unmarshal(b, &msgs); err != nil {
		return nil, err
	}

	return New(apiKey, append([]Option{WithHistory(msgs)}, opts...)...)
}

// Save the conversation to disk at the given full path.
func (c *Conversation) Save(dst string) error {
	dat, err := json.Marshal(c.History)
	if err != nil {
		return err
	}
	return os.WriteFile(dst, dat, 0655)
}

func (c *Conversation) apiCall(ctx context.Context, history []openaigo.ChatMessage) (string, error) {
	client := openaigo.NewClient(c.apiKey)
	request := openaigo.ChatCompletionRequestBody{
		Model:    c.model,
		Messages: history,
	}

	resp, err := client.Chat(ctx, request)
	if err != nil {
		return "", err

	}

	if len(resp.Choices) != 1 {
		return "", fmt.Errorf("invalid response: %+v", resp)
	}
	return resp.Choices[0].Message.Content, nil
}

func (c *Conversation) converse(ctx context.Context, role, input string) (string, error) {
	c.History = append(c.History, openaigo.ChatMessage{Role: role, Content: input})
	resp, err := c.apiCall(ctx, c.History)
	if err != nil {
		return "", err
	}
	c.History = append(c.History, openaigo.ChatMessage{Role: roleAssistant, Content: resp})
	return resp, nil
}

// System writes in the conversation as the "system" role.
// You can use a system level instruction to guide your model's behavior throughout the conversation.
// see: https://help.openai.com/en/articles/7042661-chatgpt-api-transition-guide
func (c *Conversation) System(input string) (string, error) {
	return c.converse(c.ctx, roleSystem, input)
}

// User writes in the conversation as the "user" role.
func (c *Conversation) User(input string) (string, error) {
	return c.converse(c.ctx, roleUser, input)
}

// Chat is syntax sugar. is equivalent to call User.
func (c *Conversation) Chat(input string) (string, error) {
	return c.User(input)
}

package conversation

import (
	"context"

	"github.com/otiai10/openaigo"
)

// Option is the options for the conversation.
type Option func(c *Conversation) error

// WithInitialPrompt allow to load an initial prompt to guide your model's behavior throughout the conversation.
// The prompt will be written as "system" role.
func WithInitialPrompt(s string) Option {
	return func(c *Conversation) error {
		c.History = append(c.History, openaigo.ChatMessage{Role: roleSystem, Content: s})
		return nil
	}
}

// WithModel allows to override the default model (gpt-3.5-turbo).
func WithModel(model string) Option {
	return func(c *Conversation) error {
		c.model = model
		return nil
	}
}

// WithHistory allows to inject an history in the conversation.
func WithHistory(msg []openaigo.ChatMessage) Option {
	return func(c *Conversation) error {
		c.History = msg
		return nil
	}
}

// WithContext associate a context to the conversation.
func WithContext(ctx context.Context) Option {
	return func(c *Conversation) error {
		c.ctx = ctx
		return nil
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"

	conv "github.com/mudler/go-chatgpt-conversation"
)

func main() {
	conv, err := conv.New(os.Getenv("OPENAI_API_TOKEN"))
	if err != nil {
		panic(err)
	}

	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println("Prompt:")

	for scanner.Scan() {
		line := scanner.Text()

		// do something with the line, for example, print it out
		data, err := conv.Chat(line)
		if err != nil {
			panic(err)
		}
		fmt.Println(data)
		fmt.Println("Prompt:")
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}
